 const b=ln(cx,cy,x0,y0,{w:2,end:1})+ln(cx,cy,x1,y1,{w:2,end:1})+`<path d="M${u1.toFixed(1)},${v1.toFixed(1)} A22,22 0 1 0 ${u0.toFixed(1)},${v0.toFixed(1)}" fill="none" stroke="${INK}" stroke-width="1.6"/>`+tx(lx,ly+4,`${small}°`,{size:13});
