 F.seg([-11,0],[11,0],{start:1,end:1}).seg(D,[B[0]*1.45,B[1]*1.45],{end:1}).dot([-7,0]).dot([7,0]).dot(B).txt([-7,1],'A',{italic:1}).txt([0,-1.5],'D',{italic:1}).txt([7,-1.5],'C',{italic:1}).txt([B[0]+(B[0]>0?-1:1),B[1]+0.4],'B',{italic:1});
