 counts.forEach((k,i)=>{b+=ln(cx,cy,...P(a,r),{w:1.2});const sweep=360*k/T,mid=a+sweep/2,[lx,ly]=P(mid,r*0.58);b+=tx(lx,ly-2,names[i],{size:12})+tx(lx,ly+13,String(k),{size:12});a+=sweep;});
