  +ln(x0-22,yb,x0-22,ye,{start:1,end:1,w:1})+tx(x0-26,(yb+ye)/2+4,`${low} m`,{size:12,anchor:'end'})+ln(xm,yb,xm,yp,{start:1,end:1,w:1,dash:'4,3'})+tx(xm+6,(yb+yp)/2+20,`${peak} m`,{size:12,anchor:'start'});
