 t=n(`Simplify: ${money(ap)} ÷ ${bp}. Give the answer in dollars.`,R(z,100),`${money(ap)} ÷ ${bp} = ${money(z)} because ${bp} × ${money(z)} = ${money(ap)}.`,{dividendCents:ap,divisor:bp},'decimal');
t.answer.display=money(z);
