 t=n(`Simplify: ${k}(${money(a)}). Give the answer in dollars.`,R(a*k,100),`${k} × ${money(a)} = ${money(a*k)}.`,{cents:a,factor:k},'decimal');
 t.answer.display=money(a*k);
