 const lcm=a*b/gcd(a,b);if(yes)q=lcm*k*int(1,3);else{do{q=int(100,999)+0;}while(q%a===0&&q%b===0||!(q%a===0||q%b===0));}
 yes=q%a===0&&q%b===0;
