 const [name,test]=pick(props),size=pick([[100,999],[1000,9999],[10000,99999]]);let z;do{z=int(...size);}while(!test(z));const others=[];while(others.length<3){const v=int(...size);if(!test(v)&&!others.includes(v))others.push(v);}
